package main
import (
 "fmt"
 "go/ast"
 "go/parser"
 "go/token"
 "os"
)
func main(){
 fset:=token.NewFileSet()
 f,err:=parser.ParseFile(fset, os.Args[1], nil, 0)
 if err!=nil{panic(err)}
