import subprocess, os, shutil

def max_t(name,code):
    d=f'/tmp/subtree/{name}'; shutil.rmtree(d,ignore_errors=True); os.makedirs(d); open(d+'/a.go','w').write(code)
    outs={}
    for t in range(1,40):
        r=subprocess.run(['/workspace/executable','-t',str(t)],cwd=d,capture_output=True,text=True)
        if r.stdout!=outs.get(t-1):
            outs[t]=r.stdout
            print(name,'change t',t,repr(r.stdout))
    print()

# a subtree repeated as calls within differing contexts - should be exact subtree
max_t('call','''package p
func F() { foo(1, bar(2,3), 4) }
func G() { x := 1; println(x); foo(1, bar(2,3), 4) }
''')
# expression binary nested
max_t('expr','''package p
func F() int { return (1+2)*(3+4) }
func G() int { x := (1+2)*(3+4); return x }
''')
# if subtree
max_t('if','''package p
func F() {
if x > 0 {
println(x)
} else {
println(0)
}
}
func G() {
println(1)
if x > 0 {
println(x)
} else {
println(0)
}
}
''')
# composite lit etc
max_t('slice','''package p
var A = []int{1,2,3,4}
var B = []string{"a"}
var C = []int{1,2,3,4}
''')
