import subprocess,json,sys,collections

def get_nodes(path):
    out=subprocess.check_output(['/tmp/astdump/dump',path])
    nodes=json.loads(out)
    # children list by parent
    for n in nodes: n['children']=[]
    for n in nodes:
        if n['Parent']>=0: nodes[n['Parent']]['children'].append(n['Idx'])
    return nodes

def postorder(nodes):
    res=[]
    def rec(i):
        for c in nodes[i]['children']: rec(c)
        res.append(nodes[i])
    rec(0); return res

def analyze(path, order='pre', token_mode='type', tmin=1):
    nodes=get_nodes(path)
    seq=nodes if order=='pre' else postorder(nodes)
    if order=='pre_rev': seq=list(reversed(nodes))
    if order=='post_rev': seq=list(reversed(postorder(nodes)))
    def tok(n):
        if token_mode=='type': return n['Type']
        if token_mode=='arity': return (n['Type'], len(n['children']))
        if token_mode=='subtree':
            # compute size
            return (n['Type'], subtree_size[n['Idx']])
    # subtree sizes
    subtree_size={}
    for n in reversed(nodes): subtree_size[n['Idx']]=1+sum(subtree_size[c] for c in n['children'])
    toks=[tok(n) for n in seq]
    print('SEQ',order,token_mode,'len',len(toks))
    for i,(n,tk) in enumerate(zip(seq,toks)): print(i,n['Idx'],tk,n['StartLine'],n['EndLine'])
    N=len(toks)
    occ={}
    for i in range(N):
        for l in range(tmin,N-i+1):
            key=tuple(toks[i:i+l])
            occ.setdefault(key,[]).append(i)
    cand=[]
    for key,idxs in occ.items():
        if len(idxs)<2: continue
        rights=set(); lefts=set()
        for i in idxs:
            rights.add(toks[i+len(key)] if i+len(key)<N else '$END')
            lefts.add(toks[i-1] if i>0 else '$START')
        if len(rights)>=2:
            # right maximal (internal suffix tree)
            spans=[(seq[i]['StartLine'],seq[i+len(key)-1]['EndLine']) for i in idxs]
            cand.append((key,idxs,lefts,rights,spans))
    print('--- right-branching repeats >=',tmin)
    for key,idxs,lefts,rights,spans in sorted(cand,key=lambda x:(-len(x[0]), x[1])):
        print('len',len(key),'idx',idxs,'spans',spans,'leftdiv',len(lefts),'rightdiv',len(rights),'key',[str(k) for k in key])
    print('--- maximal (left & right diverse) ')
    for key,idxs,lefts,rights,spans in sorted(cand,key=lambda x:(-len(x[0]), x[1])):
        if len(lefts)>=2:
            print('len',len(key),'idx',idxs,'spans',spans,'key',[str(k) for k in key])

path=sys.argv[1]; tmin=int(sys.argv[2]) if len(sys.argv)>2 else 1
for order in ['pre','post']:
    analyze(path,order,'type',tmin)
