import subprocess,json,sys

def nodes(path):
    out=subprocess.check_output(['/tmp/astdump/dump',path]); ns=json.loads(out)
    for n in ns:n['children']=[]
    for n in ns:
        if n['Parent']>=0:ns[n['Parent']]['children'].append(n['Idx'])
    return ns

def seqs(ns,mode):
    if mode=='pre': return ns
    if mode=='post':
        r=[]
        def rec(i):
            for c in ns[i]['children']:rec(c)
            r.append(ns[i])
        rec(0);return r

def show(path):
    ns=nodes(path)
    subtree={}
    for n in reversed(ns): subtree[n['Idx']]=1+sum(subtree[c] for c in n['children'])
    for order in ['pre','post']:
      for tmode in ['type','arity','subtree']:
        seq=seqs(ns,order)
        def tok(n):
            if tmode=='type':return n['Type'].replace('*ast.','')
            if tmode=='arity':return (n['Type'].replace('*ast.',''),len(n['children']))
            return (n['Type'].replace('*ast.',''),subtree[n['Idx']])
        toks=[tok(n) for n in seq]; N=len(toks); occ={}
        for i in range(N):
            for l in range(1,N-i+1): occ.setdefault(tuple(toks[i:i+l]),[]).append(i)
        print('\n',path,order,tmode)
        cand=[]
        for key,idxs in occ.items():
            if len(idxs)<2:continue
            rights={toks[i+len(key)] if i+len(key)<N else '$' for i in idxs}
            lefts={toks[i-1] if i>0 else '^' for i in idxs}
            parent_occ=len(occ.get(key[:-1],[])) if len(key)>1 else N
            if len(rights)>=2:
                spans=[(seq[i]['StartLine'],seq[i+len(key)-1]['EndLine']) for i in idxs]
                cand.append((len(key),idxs,spans,len(lefts),len(rights),parent_occ,key))
        for L,idxs,spans,ld,rd,po,key in sorted(cand,key=lambda x:(-x[0],x[1])):
            print(f'RB len={L} idx={idxs} spans={spans} leftdiv={ld} parentocc={po} key={key}')
        print('-- maximal --')
        for L,idxs,spans,ld,rd,po,key in sorted(cand,key=lambda x:(-x[0],x[1])):
            if ld>=2: print(f'M len={L} idx={idxs} spans={spans} key={key}')
for p in sys.argv[1:]:show(p)
