import subprocess,json,sys
from collections import defaultdict

def get_seq(path,order='post',tokenmode='arity'):
    ns=json.loads(subprocess.check_output(['/tmp/astdump/dump',path]))
    for n in ns:n['children']=[]
    for n in ns:
        if n['Parent']>=0:ns[n['Parent']]['children'].append(n['Idx'])
    # subtree sizes
    sz={}
    for n in reversed(ns):sz[n['Idx']]=1+sum(sz[c] for c in n['children'])
    seq=[]
    if order=='pre':seq=ns[:]
    else:
        def rec(i):
            for c in ns[i]['children']:rec(c)
            seq.append(ns[i])
        rec(0)
    toks=[]
    for n in seq:
        if tokenmode=='type':tok=n['Type']
        elif tokenmode=='arity':tok=(n['Type'],len(n['children']))
        elif tokenmode=='subtree':tok=(n['Type'],sz[n['Idx']])
        toks.append(tok)
    return seq,toks,sz

class Node:
    __slots__=('children','indexes','tok')
    def __init__(self):self.children={};self.indexes=[];self.tok=None

def build(toks):
    root=Node();root.indexes=list(range(len(toks)))
    for i in range(len(toks)):
        node=root
        for j in range(i,len(toks)):
            t=toks[j]
            nxt=node.children.get(t)
            if nxt is None:
                nxt=Node();nxt.tok=t;node.children[t]=nxt
            node=nxt;node.indexes.append(i)
    return root

def valid_post(seq_tokens_arity,mode):
    # tokens are (type,arity) or type with arity lookup passed separately
    stack=0
    for ar in seq_tokens_arity:
        if ar==0:
            stack+=1
        else:
            if stack < ar: # need ar items on stack to consume, but if ar>0 and stack<ar underflow
                return False,stack
            stack = stack - ar + 1
    if mode=='forest': return stack>=1,stack
    if mode=='single': return stack==1,stack
    return True,stack

def valid_pre(arity_list,mode):
    # parse forest: need is number of slots to fill for current forest; start need=1 for first tree
    need=1; trees=0
    for ar in arity_list:
        if need==0:
            # start new tree
            need=1;trees+=1
        need = need -1 + ar
    # complete if need==0 at end
    if mode=='forest':return need==0,need
    if mode=='single':return need==0 and trees==0,need
    return True,need

def simulate(path,t,order='post',tokenmode='arity',validmode='forest',report='maximal'):
    seq,toks,sz=get_seq(path,order,tokenmode)
    arity=[len(n['children']) for n in seq]
    root=build(toks)
    groups=[]
    # DFS iterative recursion with path tokens and start indexes are node.indexes
    def dfs(node,depth,path_ar):
        # check report before children?
        reported=False
        if depth>=t and len(node.indexes)>=2:
            if order=='post':ok,_=valid_post(path_ar,validmode)
            else:ok,_=valid_pre(path_ar,validmode)
            if ok:
                if report=='first':
                    groups.append((depth,tuple(node.indexes)));return
                elif report=='maximal':
                    # maximal if no child has same indexes count
                    if all(len(ch.indexes)<len(node.indexes) for ch in node.children.values()):
                        groups.append((depth,tuple(node.indexes)))
                        # continue? descendants are extensions with fewer occ; original might still report subclones with subsets.
                        # We'll not prune by default here
                elif report=='all':
                    groups.append((depth,tuple(node.indexes)))
        for tok,ch in node.children.items():
            # find arity of tok token at position? path_ar needs arity corresponding to suffix token, but all occurrences share same token; if tokenmode includes arity use it else need lookup by an occurrence
            # Use arity from first index occurrence at depth position: seq[ch.indexes[0]+depth] arity (depth is current depth, next token index = start+depth)
            ar = arity[ch.indexes[0]+depth]
            dfs(ch,depth+1,path_ar+[ar])
    dfs(root,0,[])
    out=[]
    for depth,idxs in groups:
        spans=[]
        for i in idxs:
            spans.append((seq[i]['StartLine'],seq[i+depth-1]['EndLine']))
        out.append((depth,idxs,spans))
    return out

def original(path,t,cwd):
    import subprocess,re,os
    r=subprocess.run(['/workspace/executable','-t',str(t),os.path.basename(path)],cwd=cwd,capture_output=True,text=True)
    groups=[]
    for part in r.stdout.split('found ')[1:]:
        clones=re.findall(r'a\.go:(\d+),(\d+)',part)
        groups.append([(int(a),int(b)) for a,b in clones])
    return groups

if __name__=='__main__':
    path=sys.argv[1];cwd=sys.argv[2];t=int(sys.argv[3])
    print('ORIGINAL',original(path,t,cwd))
    for order in ['post','pre']:
      for tm in ['arity','type']:
        for vm in ['forest','single']:
          for rep in ['maximal','first','all']:
            g=simulate(path,t,order,tm,vm,rep)
            print(order,tm,vm,rep,[(d,s) for d,i,s in g])
