import sys
sys.path.insert(0,'/tmp')
from sim import get_seq
from model2 import boundaries_pre

def model(path,t,left_required=True,suppress_contained=False):
    seq,toks,sz=get_seq(path,'pre','type');N=len(toks);occ={}
    for i in range(N):
        for l in range(1,N-i+1):occ.setdefault(tuple(toks[i:i+l]),[]).append(i)
    cands=[]
    for key,idxs in occ.items():
        if len(idxs)<2:continue
        rights={toks[i+len(key)] if i+len(key)<N else '$' for i in idxs}
        if len(rights)<2:continue
        if left_required:
            lefts={toks[i-1] if i>0 else '^' for i in idxs}
            if len(lefts)<2:continue
        L=len(key);common=None
        for i in idxs:
            b=boundaries_pre(seq,i,L);m={e-i:tuple(s) for e,s in b}
            common=m if common is None else {k:v for k,v in common.items() if k in m and m[k]==v}
            if not common:break
        if not common:continue
        maxlen=max(common);sizes=common[maxlen]
        segs=[];st=None
        for idx,s in enumerate(sizes):
            if s>=t:
                if st is None:st=idx
            else:
                if st is not None:segs.append((st,idx));st=None
        if st is not None:segs.append((st,len(sizes)))
        if not segs:continue
        s0,e0=segs[-1]
        spans=[];ranges=[]
        for i in idxs:
            first=i+sum(sizes[:s0]); last_root=i+sum(sizes[:e0-1]); endtok=i+sum(sizes[:e0])
            spans.append((seq[first]['StartLine'],seq[last_root]['EndLine']));ranges.append((first,endtok))
        cands.append((spans,ranges,L))
    # dedupe by spans, keep largest L for suppression?
    uniq={}
    for spans,ranges,L in cands:
        k=tuple(spans)
        if k not in uniq or L>uniq[k][1]:uniq[k]=(ranges,L)
    cands=[(list(k),v[0],v[1]) for k,v in uniq.items()]
    if suppress_contained:
        # sort by total token length of segment (range length) descending, suppress if all ranges contained in a kept group's ranges (by matching occurrence alignment? simple: each range is within some range of kept group)
        cands_sorted=sorted(cands,key=lambda x:-(x[1][0][1]-x[1][0][0]))
        kept=[]
        for spans,ranges,L in cands_sorted:
            contained=False
            for kspans,kranges,kL in kept:
                if all(any(ks<=s and e<=ke for ks,ke in kranges) for s,e in ranges):
                    contained=True;break
            if not contained:kept.append((spans,ranges,L))
        cands=kept
    return [c[0] for c in cands]
