	"path/filepath"
	"sort"
	"strings"
)

const usageText = `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
  -files
    	read file names from stdin one at each line
  -html
    	output the results as HTML, including duplicate code fragments
  -plumbing
    	plumbing (easy-to-parse) output for consumption by scripts or tools
  -t, -threshold size
    	minimum token sequence size as a clone (default 15)
  -vendor
    	check files in vendor directory
  -v, -verbose
    	explain what is being done

Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.
`

// Tok is a single serialized syntax token (one AST node).
type Tok struct {
	Typ       int
	Arity     int
	Filename  string
	StartLine int
	EndLine   int
	StartOff  int
	EndOff    int
	Sep       bool
}

type Clone struct {
	Filename  string
	StartLine int
	EndLine   int
	StartOff  int
	EndOff    int
}

type cloneGroup struct {
	clones []Clone
	ranges [][2]int // global token ranges [start,end) per clone (same order as clones before sorting)
	segLen int
	order  int
}

// ---------- AST tokenization ----------

var typeIDs = map[string]int{}
var nextTypeID = 1

func typeIDFor(node ast.Node) int {
	name := fmt.Sprintf("%T", node)
	if id, ok := typeIDs[name]; ok {
		return id
	}
	id := nextTypeID
	nextTypeID++
	typeIDs[name] = id
	return id
}

// astNodeInfo is a node in the Walk tree before pruning.
type astNodeInfo struct {
	node     ast.Node
	children []int
	parent   int
}

func buildTokensForFile(filename string, f *ast.File, fset *token.FileSet) []Tok {
	var nodes []*astNodeInfo
	var stack []int
	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			stack = stack[:len(stack)-1]
			return true
		}
		parent := -1
		if len(stack) > 0 {
			parent = stack[len(stack)-1]
		}
		idx := len(nodes)
		nodes = append(nodes, &astNodeInfo{node: n, parent: parent})
		if parent >= 0 {
			nodes[parent].children = append(nodes[parent].children, idx)
		}
		stack = append(stack, idx)
		return true
	})
	// Mark subtrees to prune.
	pruned := make([]bool, len(nodes))
	var markPruned func(int)
	markPruned = func(i int) {
		pruned[i] = true
		for _, c := range nodes[i].children {
			markPruned(c)
		}
	}
	for i, info := range nodes {
		if pruned[i] {
			continue
		}
		switch n := info.node.(type) {
		case *ast.File:
			for _, c := range info.children {
				if nodes[c].node == ast.Node(n.Name) && n.Name != nil {
					markPruned(c)
				}
			}
		case *ast.GenDecl:
			if n.Tok == token.IMPORT {
				markPruned(i)
			}
		case *ast.Field:
			if n.Tag != nil {
				for _, c := range info.children {
					if nodes[c].node == ast.Node(n.Tag) {
						markPruned(c)
					}
				}
			}
		case *ast.FuncType:
			if n.TypeParams != nil {
				for _, c := range info.children {
					if nodes[c].node == ast.Node(n.TypeParams) {
						markPruned(c)
					}
				}
			}
		case *ast.TypeSpec:
			if n.TypeParams != nil {
				for _, c := range info.children {
					if nodes[c].node == ast.Node(n.TypeParams) {
						markPruned(c)
					}
				}
			}
		case *ast.IndexListExpr:
			for _, c := range info.children {
				markPruned(c)
			}
		}
	}
	var toks []Tok
	for i, info := range nodes {
		if pruned[i] {
			continue
		}
		arity := 0
		for _, c := range info.children {
			if !pruned[c] {
				arity++
			}
		}
		sp := fset.Position(info.node.Pos())
		ep := fset.Position(info.node.End())
		toks = append(toks, Tok{
			Typ:       typeIDFor(info.node),
			Arity:     arity,
			Filename:  filename,
			StartLine: sp.Line,
			EndLine:   ep.Line,
			StartOff:  sp.Offset,
			EndOff:    ep.Offset,
		})
	}
	return toks
}

// ---------- suffix array ----------

func buildSA(s []int) []int {
	n := len(s)
	if n == 0 {
		return nil
	}
	sa := make([]int, n)
	rank := make([]int, n)
	tmp := make([]int, n)
	for i := range sa {
		sa[i] = i
		rank[i] = s[i]
	}
	// counting sort by second then first key
	countingSort := func(k int) {
		maxRank := 0
		for _, r := range rank {
			if r > maxRank {
				maxRank = r
			}
		}
		key2 := func(idx int) int {
			if idx+k < n {
				return rank[idx+k]
			}
			return 0
		}
		// sort by second key
		cnt := make([]int, maxRank+1)
		for i := 0; i < n; i++ {
			cnt[key2(sa[i])]++
		}
		sum := 0
		for i := range cnt {
			cnt[i], sum = sum, sum+cnt[i]
		}
		sa2 := make([]int, n)
		for i := 0; i < n; i++ {
			idx := sa[i]
			k2 := key2(idx)
			sa2[cnt[k2]] = idx
			cnt[k2]++
		}
		// sort by first key
		cnt = make([]int, maxRank+1)
		for i := 0; i < n; i++ {
			cnt[rank[sa2[i]]]++
		}
		sum = 0
		for i := range cnt {
			cnt[i], sum = sum, sum+cnt[i]
		}
		for i := 0; i < n; i++ {
			idx := sa2[i]
			k1 := rank[idx]
			sa[cnt[k1]] = idx
			cnt[k1]++
		}
	}
	for k := 1; k < n; k <<= 1 {
		countingSort(k)
		tmp[sa[0]] = 1
		r := 1
		for i := 1; i < n; i++ {
			cur, prev := sa[i], sa[i-1]
			cur1, prev1 := rank[cur], rank[prev]
			var cur2, prev2 int
			if cur+k < n {
				cur2 = rank[cur+k]
			}
			if prev+k < n {
				prev2 = rank[prev+k]
			}
			if cur1 != prev1 || cur2 != prev2 {
				r++
			}
			tmp[cur] = r
		}
		copy(rank, tmp)
		if r == n {
			break
		}
	}
	return sa
}

func buildLCP(s []int, sa []int) []int {
	n := len(s)
	if n <= 1 {
		return nil
	}
	rankPos := make([]int, n)
	for i, p := range sa {
		rankPos[p] = i
	}
	lcp := make([]int, n-1) // lcp[i] = LCP of sa[i] and sa[i+1]
	h := 0
	for i := 0; i < n; i++ {
		r := rankPos[i]
		if r == n-1 {
			h = 0
			continue
		}
		j := sa[r+1]
		for i+h < n && j+h < n && s[i+h] == s[j+h] {
			h++
		}
		lcp[r] = h
		if h > 0 {
			h--
		}
	}
	return lcp
}

// ---------- clone finding (maximal-repeat model) ----------

func boundariesFor(toks []Tok, pos, length int) map[int][]int {
	res := make(map[int][]int)
	var sizes []int
	i := 0
	for i < length {
		need := 1
		j := i
		for j < length && need > 0 {
			need += toks[pos+j].Arity - 1
			j++
		}
		if need != 0 {
			break
		}
		sizes = append(sizes, j-i)
		i = j
		cp := make([]int, len(sizes))
		copy(cp, sizes)
		res[i] = cp
	}
	return res
}

func equalInts(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func findClones(toks []Tok, threshold int) []*cloneGroup {
	n := len(toks)
	if n == 0 {
		return nil
	}
	// Build integer sequence: compress Typ IDs (separators are unique negative).
	seq := make([]int, n)
	uniqMap := make(map[int]int)
	var uniqVals []int
	for i, t := range toks {
		if _, ok := uniqMap[t.Typ]; !ok {
			uniqMap[t.Typ] = 0
			uniqVals = append(uniqVals, t.Typ)
		}
		_ = i
	}
	sort.Ints(uniqVals)
	for i, v := range uniqVals {
		uniqMap[v] = i + 1
	}
	for i, t := range toks {
		seq[i] = uniqMap[t.Typ]
	}
	sa := buildSA(seq)
	lcp := buildLCP(seq, sa)

	var candidates []*cloneGroup
	seenGroups := make(map[string]bool)
	orderCounter := 0

	processInterval := func(depth, lb, rb int) {
		if depth == 0 || rb-lb < 1 {
			return
		}
		if threshold > 1 && depth < threshold {
			return
		}
		occ := sa[lb : rb+1]
		// Compute common boundaries.
		var common map[int][]int
		for _, pos := range occ {
			if pos+depth > n {
				common = nil
				break
			}
			// a repeat substring must not contain a separator
			containsSep := false
			for k := 0; k < depth; k++ {
				if toks[pos+k].Sep {
					containsSep = true
					break
				}
			}
			if containsSep {
				common = nil
				break
			}
			b := boundariesFor(toks, pos, depth)
			if common == nil {
				common = b
			} else {
				for key, v := range common {
					if bv, ok := b[key]; !ok || !equalInts(bv, v) {
						delete(common, key)
					}
				}
			}
			if len(common) == 0 {
				break
			}
		}
		if len(common) == 0 {
			return
		}
		maxlen := 0
		for k := range common {
			if k > maxlen {
				maxlen = k
			}
		}
		sizes := common[maxlen]
		// rightmost segment with all sizes >= threshold
		type seg struct{ s, e int }
		var segs []seg
		start := -1
		for idx, s := range sizes {
			if s >= threshold {
				if start < 0 {
					start = idx
				}
			} else {
				if start >= 0 {
					segs = append(segs, seg{start, idx})
					start = -1
				}
			}
		}
		if start >= 0 {
			segs = append(segs, seg{start, len(sizes)})
		}
		if len(segs) == 0 {
			return
		}
		sel := segs[len(segs)-1]
		off := 0
		for i := 0; i < sel.s; i++ {
			off += sizes[i]
		}
		segLen := 0
		for i := sel.s; i < sel.e; i++ {
			segLen += sizes[i]
		}
		lastRootOff := 0
		for i := 0; i < sel.e-1; i++ {
			lastRootOff += sizes[i]
		}
		var clones []Clone
		var ranges [][2]int
		seenClone := make(map[string]bool)
		for _, pos := range occ {
			first := pos + off
			lastRoot := pos + lastRootOff
			if first >= n || lastRoot >= n {
				continue
			}
			c := Clone{
				Filename:  toks[first].Filename,
				StartLine: toks[first].StartLine,
				EndLine:   toks[lastRoot].EndLine,
				StartOff:  toks[first].StartOff,
				EndOff:    toks[lastRoot].EndOff,
			}
			key := fmt.Sprintf("%s\x00%d\x00%d", c.Filename, c.StartOff, c.EndOff)
			if seenClone[key] {
				continue
			}
			seenClone[key] = true
			clones = append(clones, c)
			ranges = append(ranges, [2]int{first, first + segLen})
		}
		if len(clones) < 2 {
			return
		}
		// dedupe groups by clone set (sorted keys)
		keys := make([]string, len(clones))
		for i, c := range clones {
			keys[i] = fmt.Sprintf("%s\x00%d\x00%d", c.Filename, c.StartOff, c.EndOff)
		}
		sortedKeys := append([]string(nil), keys...)
		sort.Strings(sortedKeys)
		gkey := strings.Join(sortedKeys, "\x01")
		if seenGroups[gkey] {
			return
		}
		seenGroups[gkey] = true
		candidates = append(candidates, &cloneGroup{clones: clones, ranges: ranges, segLen: segLen, order: orderCounter})
		orderCounter++
	}

	// Enumerate LCP intervals.
	type interval struct {
		lcp int
		lb  int
	}
	stack := []interval{{0, 0}}
	// lcp indexed between sa[i] and sa[i+1]; we iterate i=1..n-1 with cur = lcp[i-1], plus final 0.
	for idx := 1; idx <= n; idx++ {
		var cur int
		if idx < n {
			cur = lcp[idx-1]
		} else {
			cur = 0
		}
		lb := idx - 1
		for len(stack) > 0 && stack[len(stack)-1].lcp > cur {
			iv := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			processInterval(iv.lcp, iv.lb, idx-1)
			lb = iv.lb
		}
		if len(stack) == 0 || stack[len(stack)-1].lcp < cur {
			stack = append(stack, interval{cur, lb})
		}
	}

	// Suppression: same-count containment, larger segment first.
	sortedCands := append([]*cloneGroup(nil), candidates...)
	sort.SliceStable(sortedCands, func(i, j int) bool {
		return sortedCands[i].segLen > sortedCands[j].segLen
	})
	var kept []*cloneGroup
	for _, cand := range sortedCands {
		contained := false
		candRanges := append([][2]int(nil), cand.ranges...)
		sort.Slice(candRanges, func(i, j int) bool { return candRanges[i][0] < candRanges[j][0] })
		for _, k := range kept {
			if len(k.ranges) != len(cand.ranges) {
				continue
			}
			kRanges := append([][2]int(nil), k.ranges...)
			sort.Slice(kRanges, func(i, j int) bool { return kRanges[i][0] < kRanges[j][0] })
			allIn := true
			for i := range candRanges {
				if !(kRanges[i][0] <= candRanges[i][0] && candRanges[i][1] <= kRanges[i][1]) {
					allIn = false
					break
				}
			}
			if allIn {
				contained = true
				break
			}
		}
		if !contained {
			kept = append(kept, cand)
		}
	}
	sort.SliceStable(kept, func(i, j int) bool { return kept[i].order < kept[j].order })
	// Sort clones within each group.
	for _, g := range kept {
		sort.Sort(byFilenameStart(g.clones))
	}
	return kept
}

type byFilenameStart []Clone

func (b byFilenameStart) Len() int      { return len(b) }
func (b byFilenameStart) Swap(i, j int) { b[i], b[j] = b[j], b[i] }
func (b byFilenameStart) Less(i, j int) bool {
	if b[i].Filename != b[j].Filename {
		return b[i].Filename < b[j].Filename
	}
	if b[i].StartLine != b[j].StartLine {
		return b[i].StartLine < b[j].StartLine
	}
	return b[i].EndLine < b[j].EndLine
}

// ---------- printers ----------

func printDefault(w *bufio.Writer, groups []*cloneGroup) {
	for _, g := range groups {
		fmt.Fprintf(w, "found %d clones:\n", len(g.clones))
		for _, c := range g.clones {
			fmt.Fprintf(w, "  %s:%d,%d\n", c.Filename, c.StartLine, c.EndLine)
		}
	}
	fmt.Fprintf(w, "\nFound total %d clone groups.\n", len(groups))
}

func printPlumbing(w *bufio.Writer, groups []*cloneGroup) {
	for _, g := range groups {
		n := len(g.clones)
		for i, c := range g.clones {
			dup := g.clones[(i+1)%n]
			fmt.Fprintf(w, "%s:%d-%d: duplicate of %s:%d-%d\n", c.Filename, c.StartLine, c.EndLine, dup.Filename, dup.StartLine, dup.EndLine)
		}
	}
}

func htmlFragment(c Clone, cache map[string][]byte) string {
	data, ok := cache[c.Filename]
	if !ok {
		b, err := os.ReadFile(c.Filename)
		if err != nil {
			data = nil
		} else {
			data = b
		}
		cache[c.Filename] = data
	}
	if data == nil {
		return ""
	}
	start := c.StartOff
	end := c.EndOff
	if start < 0 {
		start = 0
	}
	if end > len(data) {
		end = len(data)
	}
	if start > end {
		// mimic original's slicing panic behaviour is not desirable here;
		// return empty for safety (our clones should not trigger this)
		return ""
	}
	lineStart := 0
	if start > 0 {
		if idx := bytes.LastIndexByte(data[:start], '\n'); idx >= 0 {
			lineStart = idx + 1
		}
	}
	raw := make([]byte, end-lineStart)
	copy(raw, data[lineStart:end])
	// Split into lines (keeping no trailing newline handling special).
	lines := bytes.Split(raw, []byte("\n"))
	// Compute longest common whitespace prefix among non-empty lines.
	var common []byte
	first := true
	for _, ln := range lines {
		if len(ln) == 0 {
			continue
		}
		// leading whitespace (space/tab)
		i := 0
		for i < len(ln) && (ln[i] == ' ' || ln[i] == '\t' || ln[i] == '\r') {
			i++
		}
		ws := ln[:i]
		if first {
			common = append([]byte(nil), ws...)
			first = false
		} else {
			// common prefix of common and ws
			j := 0
			for j < len(common) && j < len(ws) && common[j] == ws[j] {
				j++
			}
			common = common[:j]
		}
		if len(common) == 0 {
			break
		}
	}
	dedent := 0
	if len(common) > 0 {
		allTabs := true
		for _, b := range common {
			if b != '\t' {
				allTabs = false
				break
			}
		}
		if allTabs {
			dedent = len(common)
			for i, ln := range lines {
				if len(ln) >= dedent {
					// remove dedent tabs if present at start
					k := 0
					for k < dedent && k < len(ln) && ln[k] == '\t' {
						k++
					}
					if k == dedent {
						lines[i] = ln[dedent:]
					}
				}
			}
		}
	}
	// Pad first line: replace chars before clone start with spaces (tabs kept).
	if len(lines) > 0 {
		cloneStartInLine := start - lineStart - dedent
		if cloneStartInLine < 0 {
			cloneStartInLine = 0
		}
		ln := lines[0]
		for i := 0; i < cloneStartInLine && i < len(ln); i++ {
			if ln[i] != '\t' {
				ln[i] = ' '
			}
		}
		lines[0] = ln
	}
	return string(bytes.Join(lines, []byte("\n")))
}

func printHTML(w *bufio.Writer, groups []*cloneGroup) {
	fmt.Fprint(w, "<!DOCTYPE html>\n<meta charset=\"utf-8\"/>\n<title>Duplicates</title>\n<style>\n\tpre {\n\t\tbackground-color: #FFD;\n\t\tborder: 1px solid #E2E2E2;\n\t\tpadding: 1ex;\n\t}\n</style>\n")
	cache := make(map[string][]byte)
	for i, g := range groups {
		fmt.Fprintf(w, "<h1>#%d found %d clones</h1>\n", i+1, len(g.clones))
		for _, c := range g.clones {
			fmt.Fprintf(w, "<h2>%s:%d</h2>\n", html.EscapeString(c.Filename), c.StartLine)
			frag := htmlFragment(c, cache)
			fmt.Fprintf(w, "<pre>%s</pre>\n", html.EscapeString(frag))
		}
	}
}

// ---------- main ----------

func main() {
	log.SetFlags(log.LstdFlags)
	var (
		filesFlag    = flag.Bool("files", false, "")
		htmlFlag     = flag.Bool("html", false, "")
		plumbingFlag = flag.Bool("plumbing", false, "")
		vendorFlag   = flag.Bool("vendor", false, "")
		threshold    int
		verbose      bool
	)
	flag.IntVar(&threshold, "t", 15, "")
	flag.IntVar(&threshold, "threshold", 15, "")
	flag.BoolVar(&verbose, "v", false, "")
	flag.BoolVar(&verbose, "verbose", false, "")
	flag.Usage = func() {
		fmt.Fprint(flag.CommandLine.Output(), usageText)
	}
	flag.Parse()

	if *htmlFlag && *plumbingFlag {
		log.Fatal("you can have either plumbing or HTML output")
	}

	if verbose {
		log.Println("Building suffix tree")
	}

	var toks []Tok
	sepID := -1
	addSeparator := func() {
		toks = append(toks, Tok{Typ: sepID, Sep: true})
		sepID--
	}
	fileCount := 0
	addFile := func(filename string) {
		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, filename, nil, 0)
		if err != nil {
			log.Print(err)
			return
		}
		if fileCount > 0 {
			addSeparator()
		}
		fileCount++
		ft := buildTokensForFile(filename, f, fset)
		toks = append(toks, ft...)
	}

	if *filesFlag {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			filename := strings.TrimPrefix(scanner.Text(), "./")
			addFile(filename)
		}
	} else {
		paths := flag.Args()
		if len(paths) == 0 {
			paths = []string{"."}
		}
		for _, path := range paths {
			info, err := os.Lstat(path)
			if err != nil {
				log.Fatal(err)
			}
			if !info.IsDir() {
				addFile(path)
				continue
			}
			walkErr := filepath.Walk(path, func(p string, fi os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if fi.IsDir() {
					if !*vendorFlag && fi.Name() == "vendor" {
						return filepath.SkipDir
					}
					return nil
				}
				if strings.HasSuffix(p, ".go") {
					addFile(p)
				}
				return nil
			})
			if walkErr != nil {
				log.Fatal(walkErr)
			}
		}
	}
	// final sentinel separator
	addSeparator()

	if verbose {
		log.Println("Searching for clones")
	}
	groups := findClones(toks, threshold)

	out := bufio.NewWriter(os.Stdout)
	if *htmlFlag {
		printHTML(out, groups)
	} else if *plumbingFlag {
		printPlumbing(out, groups)
	} else {
		printDefault(out, groups)
	}
	out.Flush()
}
